import csv
import io
import re


_WIDTH = 9
_HEADER_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_ ./()%\-]*")
_CLASS_LABEL = re.compile(r"[A-Za-z][A-Za-z0-9_ (),.\-]*___\S.*", re.DOTALL)
_NUMBER = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?")


def _has_measurement_tail(row):
    if len(row) < _WIDTH:
        return False
    confidence, correct, crop_correct, *measurements = row[-6:]
    return (
        correct.strip().lower() in {"true", "false"}
        and crop_correct.strip().lower() in {"true", "false"}
        and all(
            _NUMBER.fullmatch(value.strip())
            for value in [confidence, *measurements]
        )
    )


def _find_header(records):
    fallback = None
    for index, row in enumerate(records):
        if len(row) != _WIDTH:
            continue
        if _has_measurement_tail(row):
            break
        if fallback is None:
            fallback = index
        names = [value.strip() for value in row]
        if len(set(names)) == _WIDTH and all(
            _HEADER_NAME.fullmatch(name) for name in names
        ):
            return index
    if fallback is not None:
        return fallback
    return next((index for index, row in enumerate(records) if row), None)


def _repair_width(row):
    if len(row) <= _WIDTH:
        return row + [""] * (_WIDTH - len(row))

    # The first field is quoted when necessary. Extra delimiters can occur in
    # either of the two labels before the six fixed-position measurements.
    labels = row[1:-6]
    candidates = []
    for split in range(1, len(labels)):
        truth = ",".join(labels[:split])
        prediction = ",".join(labels[split:])
        score = sum(
            value.count("___") == 1 and bool(_CLASS_LABEL.fullmatch(value))
            for value in (truth, prediction)
        )
        candidates.append((score, split, truth, prediction))

    score, _, truth, prediction = max(candidates, key=lambda item: (item[0], item[1]))
    if score == 2 or _has_measurement_tail(row):
        return [row[0], truth, prediction, *row[-6:]]

    # When the intended split cannot be inferred, retain every fragment.
    return row[:_WIDTH - 1] + [",".join(row[_WIDTH - 1:])]


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]
    records = list(
        csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
        )
    )
    header_index = _find_header(records)
    if header_index is None:
        return {"columns": [], "rows": []}
    return {
        "columns": _repair_width(records[header_index]),
        "rows": [_repair_width(row) for row in records[header_index + 1:]],
    }
